#!/usr/bin/env python3
"""Generates extra_cmds.tsv: additional query commands (ids x1..) over ws and wsbroken."""
import itertools
cmds=[]
def add(c,w='ws'):
    cmds.append((('wsbroken:' if w=='wsbroken' else '')+c))
# broken workspace: pattern expansion with a package that has a BUILD syntax error
bpats=["//...","//a/...","//e:all","//e/...","//e:x","//e","//:all","//a:all","deps(//...)","rdeps(//...,//a:x.txt)","//d:all","//... - //e/...","//e:all + //a:all","kind(rule,//...)","labels(srcs,//a:all)","buildfiles(//...)","loadfiles(//a:all)","somepath(//a:lib,//a:lib2)","allpaths(//...,//a:lib)","tests(//...)","attr(tags,fast,//...)","filter('^//a',//...)","//e:*","//e:BUILD","visible(//a:lib,//...)","siblings(//e:x)","same_pkg_direct_rdeps(//a:lib)"]
for p in bpats:
    for f in ["--keep_going","--nokeep_going","--keep_going --output=label_kind","--keep_going --output=build","--keep_going --output=xml","--keep_going --output=location","--keep_going --output=package","--keep_going --order_output=full"]:
        add(f"query '{p}' {f}",'wsbroken')
# regular workspace extras
exprs=["//a:lib","//a:all","//b:all","//...","deps(//b:t1)","deps(//a:gg)","//a:gg","//b:t1","//b:tool","@ext//lib:all","//:all_tests","//:tagged"]
flags=["--noimplicit_deps","--notool_deps","--nonodep_deps","--noimplicit_deps --output=xml","--output=xml --xml:default_values","--output=xml --noxml:line_numbers","--output=build --noimplicit_deps","--output=proto --proto:default_values=false","--output=proto --noproto:locations","--output=proto --proto:output_rule_attrs=srcs,deps","--output=jsonproto --proto:rule_classes","--output=textproto --proto:flatten_selects=false","--output=label_kind --relative_locations","--output=location --relative_locations","--output=build --consistent_labels","--output=label --line_terminator_null","--output=streamed_proto --proto:rule_inputs_and_outputs=false","--output=proto --proto:include_synthetic_attribute_hash","--order_output=full --output=label_kind","--output=graph --nograph:factored","--output=graph --graph:node_limit=20","--output=minrank --order_output=full","--output=maxrank --order_output=full"]
for e in exprs:
    for f in flags:
        add(f"query '{e}' {f} --keep_going")
# functions and error cases
fn=["attr(tags,'fast',//...)","attr(visibility,'public',//...)","attr(srcs,'x.txt',//a:all)","kind('rule',//a:*)","kind('source file',//a:*)","kind('generated file',//a:*)","filter('lib',//a:all)","labels(outs,//a:gg)","labels(srcs,//a:lib)","labels(deps,//a:cl)","labels(data,//b:t1)","tests(//:all_tests)","tests(//...)","tests(//:tagged)","rdeps(//...,//a:x.txt,2)","deps(//a:lib2,1)","deps(//...,0)","some(//a:all)","some(//nonexist:x)","somepath(//a:cl,//a:cl2)","allpaths(//a:cl,//a:cl2)","buildfiles(//a:lib)","loadfiles(//a:lib)","rbuildfiles(defs.bzl)","rbuildfiles(a/BUILD)","visible(//b:shlib,//a:all)","visible(//a:lib,//b:all)","same_pkg_direct_rdeps(//a:x.txt)","siblings(//a:lib)","//a:lib +","//a:lib ^ //a:lib2","let x = //a:all in $x - //a:lib","let x = //a:all in $y","deps(//a:lib, -1)","deps(//a:lib, x)","filter(//a:lib)","deps()","kind(//a:lib,//a:lib)","attr(tags)","bogus(//a:lib)","//a:lib:","//a:lib//","@@ext+//lib:all","@@//a:lib","@ext//lib:gen","@ext//lib:*","@nonexist//x:y","//external:all","@bazel_tools//platforms:all","//a:nope","//nonexistent:all","//nonexistent/...","//a/...","//a/... - //a:lib","//a:*","//a:BUILD","//a:x.txt","//a:gg.out","//b:mk.txt","//:top.txt","//c:d.txt","//d:missing.txt","deps(//d:bad)","labels(srcs,//d:bad)","rdeps(//d:all,//c:cdata)","//pg:all","//:pg","visible(//b:shlib,//c:cdata)","tests(//b:t1)","tests(//b:t1 + //b:t2)","//a:lib - //a:lib","set(//a:lib //a:lib2)","set()","//a:lib /* c */","deps(//b:all) except //b:t1","deps(//a:cl) intersect deps(//a:cl2)","//a:lib union //a:lib2"]
for e in fn:
    for f in ["--keep_going","--nokeep_going"]:
        add(f"query '{e}' {f}")
# flag parsing / misc
misc=["query //a:lib --output=bogus","query //a:lib --order_output=bogus","query //a:lib --noorder_results","query //a:lib --order_results","query //a:lib --nohost_deps","query //a:lib --host_deps","query //a:lib --tool_deps=false","query //a:lib --universe_scope=//...","query //a:lib --universe_scope=//a:all --infer_universe_scope","query //a:lib --universe_scope=//b:all","query //b:t1 --universe_scope=//a:all","query 'deps(//b:t1)' --universe_scope=//b:all --order_output=no","query //a:lib --output_file=/nonexistent/x/y","query //a:lib --query_file=/dev/null","query --query_file=/nonexistent/q","query","query ''","query ' '","query //a:lib //a:lib2","query //a:lib + //a:lib2","query //a:lib -k","query -k //a:lib","query -k","query --keep_going=0 //a:lib","query //a:lib --nofetch","query //a:lib --noblock_for_lock","query //a:lib --graph:node_limit=x","query //a:lib --output=graph --graph:node_limit=-1","query //a:lib --incompatible_package_group_includes_double_slash=false --output=build","query '//pg:all' --output=build --incompatible_package_group_build_output","query //:pg --output=xml","query //:pg --output=proto","query --experimental_graphless_query=true //a:lib","query --experimental_graphless_query=true //a:lib --order_output=full","query --noexperimental_graphless_query //a:lib","query --output=label_kind --order_output=no //a:all","query //a:all --order_output=no","query //a:all --order_output=deps","query //a:all --order_output=full","query --noshow_progress //a:lib","query --show_progress //a:lib","query --noprogress_in_terminal_title //a:lib","query //a:lib --color=yes","query //a:lib --curses=no","query //a:lib --verbose_failures","query //a:lib --incompatible_foo","query //a:lib --nonexistent_flag","query //a:lib --output","query //a:lib --output=","query //a:lib --proto:output_rule_attrs=bogus --output=proto","query --noimplicit_deps 'deps(//a:gg)' --output=label","query --consistent_labels 'deps(@ext//lib:gen)'","query --consistent_labels //a:lib --output=label_kind","query --consistent_labels @ext//lib:all --output=build"]
for m in misc: add(m)
open('extra_cmds.tsv','w').write(''.join(f"x{i+1}\t{c}\n" for i,c in enumerate(cmds)))
print(len(cmds))
